import 'package:flutter/material.dart';import 'package:sehatak/core/models/pregnancy/pregnancy_models.dart';import 'package:sehatak/core/services/pregnancy_service.dart';class PregnancyClinicDetailScreen extends StatelessWidget{final String clinicId;const PregnancyClinicDetailScreen({super.key,required this.clinicId});@override Widget build(BuildContext c)=>Scaffold(appBar:AppBar(title:const Text('تفاصيل العيادة')),body:FutureBuilder<List<PregnancyClinic>>(future:PregnancyService().streamClinics(limit:50).first,builder:(c,s){if(!s.hasData)return const Center(child:CircularProgressIndicator());final list=s.data!.where((x)=>x.id==clinicId);if(list.isEmpty)return const Center(child:Text('العيادة غير موجودة'));final d=list.first;return ListView(padding:const EdgeInsets.all(20),children:[const Icon(Icons.local_hospital,size:70),const SizedBox(height:12),Text(d.name,textAlign:TextAlign.center,style:const TextStyle(fontSize:22,fontWeight:FontWeight.w800)),Text(d.type,textAlign:TextAlign.center),const SizedBox(height:16),Text('العنوان: ${d.address}'),Text('الهاتف: ${d.phone}'),Text('التقييم: ${d.rating.toStringAsFixed(1)}'),Text(d.isOpen?'مفتوح الآن':'مغلق الآن')]);}));}}
